#!/bin/bash
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
# Variant B of the unified dose-action design, "run variant B anyway" after variant A,:
# --orth-split 1,5 --dose-history 7 = no FiLM transport; each visit is generated by simulating its dosing history (7 doses every
# 24 h from the drug-free state of the encoded physiology = the cohort's own design, gen_tacro_confound default), each dose a
# learned translation inside the 6-D drug subspace, the flow restricted to that subspace, zero at drug-free states, with a linear
# elimination term. Physiology (4-D) conserved exactly. Question: does a model that can dose at any time keep FiLM's accuracy?
#   train   windowed s4 N=100 (confound_vc00_s4_pnoise_win_n100), 6000 epochs, main FiLM config otherwise, seeds 1-3
#   score   ep6000 on in / lo / hi, scaler pinned, seeded -> results/s4_doseh/eval/ep006000_dh7_osplit1-5_n100_s<s>_on_<reg>.json
#   check   scripts/theory/doseh_check.py (conservation, contraction / steady state, dose response) -> results/s4_doseh/check_dh7.txt
#   table   scripts/s4/doseh_table.py -> results/s4_doseh/doseh_table.txt (vs Table 3 FiLM and variant A osplit1-5)
# Markers in logs/chain_doseh.log: DOSEH_TRAINED, DOSEH_DONE. Do not edit while running.
cd $REPO_ROOT
PY=${PYTHON:-python3}
B=confound_vc00_s4_pnoise_win; T=${B}_n100; R=results/s4_doseh
mkdir -p $R/eval logs
say () { echo "[$(date '+%F %T')] $*"; }
export OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 VECLIB_MAXIMUM_THREADS=1
TAG=noz0_sig0.05_sc141.27_dech50_sel-mse_v2_decres_osplit1-5_dh7
SEEDS="1 2 3"
for s in $SEEDS; do
  D=$R/dh7_osplit1-5_n100_s$s; mkdir -p $D/exp_film_run/$T
  nohup nice -n 5 $PY run_models.py --niters 6000 -n 200 -s 40 -l 10 --dataset PK_Tacro --latent-ode --use_film \
    --noise-weight 0.01 --max-t 5. -b 512 --seed $s --experiment $T --film-no-z0-cond --obsrv-std 0.05 \
    --film-self-consistency 141.27 --decoder-hidden 50 --decoder-residual --select-on mse_v2 --patience 1000000 \
    --static-dim 4 --orth-split 1,5 --dose-history 7 --dose-interval 24 --save ./$D/ --eval-every 300 --ckpt-every 300 \
    --log-suffix __dh7_osplit1-5_s$s > logs/train_dh7_osplit1-5_s$s.log 2>&1 &
  say "launched dh7 osplit 1-5 seed $s (pid $!)"; sleep 5
done
ck () { echo $R/dh7_osplit1-5_n100_s$1/exp_film_run/$T/traj/experiment_film_${T}__${TAG}_ep006000.ckpt; }
for s in $SEEDS; do
  while [ ! -f "$(ck $s)" ]; do
    pgrep -f "log-suffix __dh7_osplit1-5_s$s" >/dev/null || { sleep 30; [ -f "$(ck $s)" ] || { say "TRAINING DIED dh7 s$s"; break; }; }
    sleep 60
  done
done
say "DOSEH_TRAINED"
for s in $SEEDS; do
  C=$(ck $s); [ -f "$C" ] || continue
  for reg in in lo hi; do
    case $reg in in) ex=$B;; *) ex=${B}_$reg;; esac
    nice -n 5 $PY scripts/confound_eval/seeded_eval.py --eval-seed 0 test_film_matched.py --experiment $ex --data-dir ./results/exp_film_run \
      --ckpt $C --scale-from $T --eval-split test --label dh7_osplit1-5_s${s}_$reg --out-json $R/eval/ep006000_dh7_osplit1-5_n100_s${s}_on_$reg.json \
      > logs/eval_dh7_osplit1-5_s${s}_$reg.log 2>&1 &
  done
  wait
  say "scored dh7 s$s"
done
OMP_NUM_THREADS=2 $PY scripts/theory/doseh_check.py $B $T $(for s in $SEEDS; do ck $s; done) > $R/check_dh7.txt 2> logs/doseh_check.err
say "check -> $R/check_dh7.txt"
$PY scripts/s4/doseh_table.py > $R/doseh_table.txt 2> logs/doseh_table.err
say "table -> $R/doseh_table.txt"
say "DOSEH_DONE"
